// visualization.js

// Set up dimensions
const container = document.getElementById('chart');
const width = container.clientWidth;
const height = container.clientHeight;

// Formatters
const formatMarketCap = (val) => {
    if (!val || val === 0 || isNaN(val)) return "N/A";
    if (val >= 1e12) return (val / 1e12).toFixed(2) + "T";
    if (val >= 1e9) return (val / 1e9).toFixed(2) + "B";
    if (val >= 1e6) return (val / 1e6).toFixed(2) + "M";
    return val.toLocaleString();
};

// Load data
d3.csv("data/stock-descriptions.csv").then(data => {
    // Process data
    data.forEach(d => {
        d.marketCapVal = d.marketCap ? +d.marketCap : 0;
        d.isETF = d.sector === 'ETF';
    });

    // Unique sectors
    const sectors = Array.from(new Set(data.map(d => d.sector))).sort();

    // Color scale
    const colorScale = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeCategory10);

    // Size scale (Market Cap -> Radius)
    // Filter out ETFs for domain calculation to avoid 0 skewing
    const marketCaps = data.filter(d => !d.isETF).map(d => d.marketCapVal);
    const minCap = d3.min(marketCaps);
    const maxCap = d3.max(marketCaps);

    const radiusScale = d3.scaleSqrt()
        .domain([minCap, maxCap])
        .range([15, 60]); // Adjust min/max radius as needed

    const getRadius = (d) => {
        if (d.isETF) return 20; // Uniform size for ETFs
        return radiusScale(d.marketCapVal);
    };

    // Calculate Sector Centers
    const centers = {};
    const radius = Math.min(width, height) * 0.3; // Distance from center
    sectors.forEach((s, i) => {
        const angle = (i / sectors.length) * 2 * Math.PI - Math.PI / 2; // Start from top
        centers[s] = {
            x: width / 2 + Math.cos(angle) * radius,
            y: height / 2 + Math.sin(angle) * radius
        };
    });

    // SVG Container
    const svg = d3.select("#chart")
        .append("svg")
        .attr("width", width)
        .attr("height", height)
        .attr("viewBox", [0, 0, width, height]);

    // Force Simulation
    const simulation = d3.forceSimulation(data)
        .force("charge", d3.forceManyBody().strength(-5)) // Weak repulsion
        .force("x", d3.forceX(d => centers[d.sector].x).strength(0.1))
        .force("y", d3.forceY(d => centers[d.sector].y).strength(0.1))
        .force("collide", d3.forceCollide(d => getRadius(d) + 2).strength(0.9));

    // Tooltip
    const tooltip = d3.select("#tooltip");

    // Draw Bubbles
    const nodes = svg.selectAll(".node")
        .data(data)
        .join("g")
        .attr("class", "node")
        .call(d3.drag()
            .on("start", dragstarted)
            .on("drag", dragged)
            .on("end", dragended));

    const circles = nodes.append("circle")
        .attr("class", "bubble")
        .attr("id", d => "bubble-" + d.ticker)
        .attr("r", d => getRadius(d))
        .attr("fill", d => colorScale(d.sector))
        .attr("stroke", "#fff")
        .attr("stroke-width", 1)
        .on("mouseover", function(event, d) {
            if (d.isETF) return;
            tooltip.classed("hidden", false)
                .html(`<strong>${d.ticker}</strong><br>${d['full name']}<br>${d.sector}`)
                .style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY + 10) + "px");

            d3.select(this).attr("stroke", "#333").attr("stroke-width", 2);
        })
        .on("mousemove", function(event) {
            tooltip.style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY + 10) + "px");
        })
        .on("mouseout", function(event, d) {
            tooltip.classed("hidden", true);
            if (!d3.select(this).classed("selected")) {
                d3.select(this).attr("stroke", "#fff").attr("stroke-width", 1);
            } else {
                 d3.select(this).attr("stroke", "#333").attr("stroke-width", 3);
            }
        })
        .on("click", (event, d) => {
            selectStock(d.ticker);
            event.stopPropagation();
        });

    // Labels
    nodes.append("text")
        .attr("class", "bubble-label")
        .attr("dy", ".3em")
        .text(d => d.ticker);

    // Simulation Tick
    simulation.on("tick", () => {
        nodes.attr("transform", d => `translate(${d.x},${d.y})`);
    });

    // Drag functions
    function dragstarted(event, d) {
        if (!event.active) simulation.alphaTarget(0.3).restart();
        d.fx = d.x;
        d.fy = d.y;
    }

    function dragged(event, d) {
        d.fx = event.x;
        d.fy = event.y;
    }

    function dragended(event, d) {
        if (!event.active) simulation.alphaTarget(0);
        d.fx = null;
        d.fy = null;
    }

    // Legend
    const legend = d3.select("#legend");
    sectors.forEach(sector => {
        const item = legend.append("div").attr("class", "legend-item");
        item.append("div")
            .attr("class", "legend-color")
            .style("background-color", colorScale(sector));
        item.append("span").text(sector);
    });

    // ---- Table Logic ----
    const tableBody = d3.select("#stock-table tbody");
    const rows = tableBody.selectAll("tr")
        .data(data)
        .join("tr")
        .attr("id", d => "row-" + d.ticker)
        .on("click", (event, d) => {
            selectStock(d.ticker);
        });

    rows.append("td").text(d => d.ticker);
    rows.append("td").text(d => d['full name']);
    rows.append("td").text(d => d.sector);
    rows.append("td").text(d => d.isETF ? "N/A" : formatMarketCap(d.marketCapVal));

    // ---- Interaction Logic ----
    let currentSelection = null;

    function selectStock(ticker) {
        // Clear previous selection
        if (currentSelection) {
            d3.select("#bubble-" + currentSelection).classed("selected", false)
                .attr("stroke", "#fff").attr("stroke-width", 1);
            d3.select("#row-" + currentSelection).classed("selected", false);
        }

        if (currentSelection === ticker) {
            currentSelection = null; // Toggle off
            return;
        }

        currentSelection = ticker;

        // Highlight Bubble
        const bubble = d3.select("#bubble-" + ticker);
        bubble.classed("selected", true)
            .attr("stroke", "#333").attr("stroke-width", 3);

        // Highlight Row
        const row = d3.select("#row-" + ticker);
        row.classed("selected", true);

        // Scroll row into view
        row.node().scrollIntoView({ behavior: "smooth", block: "center" });
    }

    // Click on background to clear selection
    d3.select("#chart").on("click", () => {
        if (currentSelection) {
            d3.select("#bubble-" + currentSelection).classed("selected", false)
                 .attr("stroke", "#fff").attr("stroke-width", 1);
            d3.select("#row-" + currentSelection).classed("selected", false);
            currentSelection = null;
        }
    });

});

